    ) ON DUPLICATE KEY UPDATE
        title_hindi = VALUES(title_hindi),
        title_english = VALUES(title_english),
        subtitle_hindi = VALUES(subtitle_hindi),
        duration_text = VALUES(duration_text),
        audio_url = VALUES(audio_url),
        lyrics_hindi = VALUES(lyrics_hindi),
        is_published = VALUES(is_published),
        display_order = VALUES(display_order),
        youtube_search_query = VALUES(youtube_search_query)
    ");

    $count = 0;
    foreach ($tracks as $t) {
        $st->execute([
            ':tk' => $t['track_key'],
            ':th' => $t['title_hindi'],
            ':te' => $t['title_english'],
            ':sh' => $t['subtitle_hindi'],
            ':dt' => $t['duration_text'],
            ':au' => $t['audio_url'],
            ':lh' => $t['lyrics_hindi'],
            ':ip' => $t['is_published'],
            ':do' => $t['display_order'],
            ':yq' => $t['youtube_search_query']
        ]);
        $count++;
    }

    echo json_encode(['success' => true, 'migrated' => $count]);
} catch (Throwable $e) {
    echo json_encode(['success' => false, 'error' => $e->getMessage()]);
}
